const raw = $input.first().json || {};
const input = raw.body || raw.json || raw;
const service_type_id = input.service_type_id || 'INST';
const measurement_type = String(input.measurement_type || 'Directa').toLowerCase();
const contractor_name = input.contractor_name || null;
const or_group = input.network_operator_group || 'ENEL_AIRE_EMCALI_AFINIA';

const hoursCol = measurement_type.includes('semi') ? 'semidirect_hours'
               : measurement_type.includes('ind')  ? 'indirect_hours'
               : 'direct_hours';

const contractorFilter = contractor_name
  ? `AND c.contractor_name ILIKE '%${String(contractor_name).replace(/'/g, "''")}%'`
  : '';

const sql = `SELECT
  ot.service_type_id,
  ot.operation_type,
  ot.${hoursCol} AS hours_required,
  c.contractor_name,
  tc.activity_name,
  tc.network_operator_group,
  tc.base_rate_cop,
  ROUND(tc.base_rate_cop * ot.${hoursCol}) AS estimated_cost_cop
FROM operation_types ot
CROSS JOIN tariff_catalog tc
JOIN contractors c ON c.id::text = tc.contractor_id
WHERE ot.service_type_id = '${service_type_id}'
  AND tc.network_operator_group = '${or_group}'
  AND ot.${hoursCol} IS NOT NULL
  AND ot.${hoursCol} > 0
  ${contractorFilter}
ORDER BY estimated_cost_cop
LIMIT 30`;

return [{ json: { sql } }];

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { result: 'Sin datos de tarifa para esos parámetros', rows: [], count: 0 } }];
const costs = rows.map(r => r.estimated_cost_cop).filter(Boolean);
const avg = costs.length ? Math.round(costs.reduce((a,b) => a+b, 0) / costs.length) : 0;
const min = costs.length ? Math.min(...costs) : 0;
const max = costs.length ? Math.max(...costs) : 0;
return [{ json: { result: 'OK', rows, count: rows.length, summary: { avg_cop: avg, min_cop: min, max_cop: max } } }];
